'use client';
import * as React from 'react';
import { useControlSize } from '../../internal/controlSize';
import { pressFocuses } from '../../internal/affix';
import { useMergedRef, cn, domId, isInvalid, oneOf, SIZES } from '../../internal/cn';
import { compare, datePattern, formatDate, isoDate, parseDate, toDay } from '../../internal/dates';
import { reject } from '../../internal/rejectInput';
import { useAnchoredLayer } from '../../internal/useAnchoredLayer';
import { useExit } from '../../internal/useExit';
import { Calendar, type DatePreset } from '../Calendar/Calendar';
import type { CalendarSystem } from '../../internal/calendars';
import { InputAction } from '../Input/Input';
import { named } from '../../internal/component';
import { useFieldControl } from '../../internal/field';
import { useLocale, useOwnLang, useSettings } from '../../internal/provider';
import { useFormReset } from '../../internal/useFormReset';
import * as icons from '../../material/builtin';
import { isComposing } from '../../internal/ime';
import { NAME_HOW, useNameCheck } from '../../internal/nameCheck';
import { en as words } from './labels';
import { windowBlur } from '../../internal/focus';
import { useControllable } from '../../internal/controllable';
import { useOpenState, type OpenChangeDetails, type OpenChangeReason } from '../../internal/openChange';

export interface DatePickerProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size' | 'value' | 'defaultValue' | 'onChange' | 'min' | 'max' | 'children'> {
  /** The chosen day (controlled), or null. Use with onValueChange. A "yyyy-mm-dd" string is that day, wherever the
      browser is (a Date made from one is UTC midnight, the day before west of Greenwich). */
  value?: Date | string | null | undefined;
  /** The chosen day at first (uncontrolled), as a Date or "yyyy-mm-dd". */
  defaultValue?: Date | string | null | undefined;
  /** Called with the new day (local midnight) and details (iso: the same day as "yyyy-mm-dd"), or null and iso null when the field is cleared. */
  onValueChange?: ((value: Date | null, details: { iso: string | null }) => void) | undefined;
  /** Called when typed text is put back on blur or Enter: "unreadable" when it isn't a date, "unavailable" when it
      is one that can't be chosen (outside min..max, or isDateDisabled). The field also says so to screen readers. */
  onInvalidInput?: ((text: string, reason: 'unreadable' | 'unavailable') => void) | undefined;
  /** The earliest and latest days that can be chosen, as Dates or "yyyy-mm-dd". */
  min?: Date | string | undefined;
  /** The latest day that can be chosen, as a Date or "yyyy-mm-dd". */
  max?: Date | string | undefined;
  /** Days that can't be chosen, such as weekends. */
  isDateDisabled?: ((date: Date) => boolean) | undefined;
  /** A BCP 47 locale for the typed format, names and first day of the week. Default: the nearest SerupaProvider's locale, else the browser's. */
  locale?: string | undefined;
  /** The calendar system the popup's months follow, as Calendar's calendar: "persian", "islamic-umalqura",
      "buddhist", "japanese" or "roc". The typed date stays Gregorian, so it reads back as the same day. Default:
      "gregory". */
  calendar?: CalendarSystem | undefined;
  /** 0 Sunday … 6 Saturday. Default: the locale's. */
  weekStartsOn?: number | undefined;
  /** A column of week numbers before the days (ISO 8601), as Calendar's weekNumbers. Default: false. */
  weekNumbers?: boolean | undefined;
  /** 'sm', 'md' (default) or 'lg', like Input. */
  size?: 'sm' | 'md' | 'lg' | undefined;
  /** A danger border and aria-invalid, like Input. */
  invalid?: boolean | undefined;
  /** The calendar button's name. Default: "Choose a date". */
  buttonLabel?: string | undefined;
  /** Shortcuts beside the calendar in the popup: true for "Today", "Tomorrow" and "In a week", or your own, as on
      Calendar. Picking one picks its day and closes the popup. */
  presets?: boolean | DatePreset[] | undefined;
  /** Whether the calendar popup shows (controlled). Use with onOpenChange. Opened this way, focus stays where it is. */
  open?: boolean | undefined;
  /** Shows the calendar popup at first (uncontrolled), without moving focus into it. Default: false. */
  defaultOpen?: boolean | undefined;
  /** Called when the popup asks to open or close, with why: { reason: 'trigger' | 'escape' | 'outside' | 'blur' | 'select' | 'api' }. */
  onOpenChange?: ((open: boolean, details: OpenChangeDetails) => void) | undefined;
}

function DatePickerRender({ ref, ...props }: DatePickerProps & React.RefAttributes<HTMLInputElement>) {
  const nameRef = useNameCheck('DatePicker', NAME_HOW.field);   // warns when it has no accessible name
  props = useFieldControl(props);   // the props a surrounding Field hands it, at any depth
  const sds = useSettings(words);
  const { value: _v, defaultValue: _d, onValueChange, open: _o, defaultOpen: _do, onOpenChange, onInvalidInput, min: minIn, max: maxIn, isDateDisabled, locale: localeProp, calendar, weekStartsOn, weekNumbers, size: _s, invalid: _i, buttonLabel, presets, className, style, name, placeholder, disabled, readOnly, onBlur, onKeyDown, ...rest } = props;
  const locale = useLocale(localeProp), lang = useOwnLang(localeProp);
  const size = oneOf(SIZES, useControlSize(props.size), 'md');
  const invalid = isInvalid(props.invalid, rest['aria-invalid']);
  const [held, setOwn, controlled] = useControllable<Date | string | null>(props.value, toDay(props.defaultValue, 'DatePicker'), 'DatePicker', 'value');
  const value = controlled ? toDay(held, 'DatePicker') : (held as Date | null);
  const min = toDay(minIn, 'DatePicker') || undefined, max = toDay(maxIn, 'DatePicker') || undefined;
  const [text, setText] = React.useState(value ? formatDate(value, locale) : '');
  const off = !!disabled || !!readOnly;
  const [open, setOpen] = useOpenState(props.open, props.defaultOpen, onOpenChange, 'DatePicker', off);
  // Focus goes into the calendar when the person opens it (the button, Alt+ArrowDown), not when it shows on arrival
  // (defaultOpen) or because the app set open.
  const [focusIn, setFocusIn] = React.useState(false);
  const openByHand = () => { setFocusIn(true); setOpen(true, 'trigger'); };
  const id = domId('srp-dp', React.useId());
  const field = React.useRef<HTMLInputElement | null>(null);
  const button = React.useRef<HTMLButtonElement | null>(null);
  const box = React.useRef<HTMLSpanElement | null>(null);
  const panel = React.useRef<HTMLDivElement | null>(null);
  // The value and locale the text was last written for: state, so a render can compare without reading a ref.
  // Primitives, so writing the same one again draws nothing (a redraw would put the text back over what's typed).
  const [seenAt, setSeenAt] = React.useState(value ? value.getTime() : null);
  const [seenLocale, setSeenLocale] = React.useState(locale);
  useFormReset(field, () => {
    if (controlled) return;
    const d = toDay(props.defaultValue);
    setSeenAt(d ? d.getTime() : null); setOwn(d); setText(d ? formatDate(d, locale) : ''); setOpen(false, 'api');
  });
  // A new value from outside, or a new locale (the browser's, once a server-rendered page hydrates), rewrites the text.
  if ((value ? value.getTime() : null) !== seenAt || locale !== seenLocale) {
    setSeenAt(value ? value.getTime() : null); setSeenLocale(locale);
    const t = value ? formatDate(value, locale) : ''; if (t !== text) setText(t);
  }

  const allowed = (d: Date) => !(min && compare(d, min) < 0) && !(max && compare(d, max) > 0) && !(isDateDisabled && isDateDisabled(d));
  const commit = (d: Date | null) => {
    setSeenAt(d ? d.getTime() : null);
    setText(d ? formatDate(d, locale) : '');
    if ((d ? d.getTime() : null) === (value ? value.getTime() : null)) return;
    if (!controlled) setOwn(d);
    if (onValueChange) onValueChange(d, { iso: d ? isoDate(d) : null });
  };
  const [rejected, setRejected] = React.useState('');   // what was said about typed text put back, shown under the field
  const read = () => {
    if (text.trim() === '') return commit(null);
    const d = parseDate(text, locale);
    if (d && allowed(d)) return commit(d);
    reject(text, d ? 'unavailable' : 'unreadable', onInvalidInput, sds.labels.inputNotAccepted, setRejected);
    commit(value);
  };
  const close = (focusField: boolean, reason: OpenChangeReason) => { setOpen(false, reason); setFocusIn(false); if (focusField && field.current) field.current.focus(); };

  // A press outside the calendar and its button, or focus moving past them (Tab), closes it.
  // The calendar stays (inert) while the popup fades out (DZ1).
  const exit = useExit(open, panel);
  useAnchoredLayer(open, panel, box, { placement: 'bottom-start', offsetVar: '--srp-dp-offset', onOutside: () => close(false, 'outside'), onFocusOutside: () => close(false, 'blur'), inside: button });

  const typed = parseDate(text, locale);
  const mergedRef = useMergedRef(ref, (n) => { field.current = n; nameRef(n); });
  return (
    <>
    <span ref={box} className={cn('srp-input', 'srp-input--size-' + size, 'srp-date-picker', invalid && 'srp-input--invalid', disabled && 'srp-input--disabled', readOnly && 'srp-input--readonly', className)} data-invalid={invalid ? '' : undefined} data-disabled={disabled ? '' : undefined} data-readonly={readOnly ? '' : undefined} style={style} data-component="date-picker" data-state={open ? 'open' : 'closed'} data-size={size} onMouseDown={(e) => pressFocuses(field)(e)}>
      <input {...rest} ref={mergedRef}
        lang={rest.lang ?? lang} type="text" inputMode="numeric" autoComplete={rest.autoComplete || 'off'} className="srp-input__field" value={text} disabled={disabled} readOnly={readOnly}
        placeholder={placeholder != null ? placeholder : datePattern(locale)} aria-invalid={invalid || undefined} aria-describedby={cn(rest['aria-describedby'], id + '-format', rejected && id + '-rejected')}
        onChange={(e) => { setText(e.target.value); setRejected(''); }}
        onBlur={(e) => { if (!windowBlur(e)) read(); if (onBlur) onBlur(e); }}
        onKeyDown={(e) => {
          if (onKeyDown) onKeyDown(e);
          if (e.defaultPrevented || isComposing(e)) return;
          if (e.key === 'Enter') read();
          else if (e.key === 'ArrowDown' && e.altKey && !off) { e.preventDefault(); read(); openByHand(); }
        }} />
      <span className="srp-input__actions">
        <InputAction ref={button} className="srp-date-picker__button" icon={icons.CalendarToday} label={buttonLabel || sds.labels.chooseDate} aria-haspopup="dialog" aria-expanded={open} aria-controls={open ? id : undefined}
          disabled={off} onClick={() => { if (open) close(false, 'trigger'); else { read(); openByHand(); } }} />
      </span>
      {/* The format to type, read after the field's name: a placeholder is gone once something is typed, and not every screen reader reads it. */}
      <span id={id + '-format'} hidden>{sds.labels.formatHint(datePattern(locale))}</span>
      {name ? <input type="hidden" name={name} form={rest.form} value={value ? isoDate(value) : ''} disabled={disabled} /> : null}
      <div ref={panel} id={id} role="dialog" aria-label={buttonLabel || sds.labels.chooseDate} {...{ popover: 'manual' }} hidden={!open || undefined} inert={!open || undefined} data-instant={exit.instant ? '' : undefined} className="srp-date-picker__popup"
        onKeyDown={(e) => { if (e.key === 'Escape' && !isComposing(e)) { e.preventDefault(); e.stopPropagation(); close(true, 'escape'); } }}>
        {open || exit.leaving ? <Calendar value={value} defaultMonth={(typed && allowed(typed) ? typed : null) || value || undefined} min={min} max={max} isDateDisabled={isDateDisabled} locale={locale} calendar={calendar} weekStartsOn={weekStartsOn} weekNumbers={weekNumbers} presets={presets} autoFocus={focusIn}
          onValueChange={(d) => { commit(d); close(true, 'select'); }} /> : null}
      </div>
    </span>
      {/* Why typed text was put back (GR232): until the text changes; said out loud already, and read with the field. */}
      {rejected && <span id={id + '-rejected'} className="srp-input-rejected">{rejected}</span>}
    </>
  );
}

/* DatePicker: a text field for a date with a calendar button. People type a date in the locale's numeric order
   (mm/dd/yyyy in en-US, dd.mm.yyyy in de-DE, or yyyy-mm-dd anywhere) or pick one in a Calendar in a popover
   dialog. Typed text is read on blur and on Enter: a date it can't read, or one outside min..max, puts back the
   last good value. The popover opens on the button (or Alt+ArrowDown in the field) with focus on the chosen day,
   and closes on a pick, Escape (returning focus to the field), a click outside or focus moving past it. With name, a hidden input sends
   yyyy-mm-dd. ref goes to the text field. */
/** A date field: type a date or pick one from a calendar popover. */
export const DatePicker = /* @__PURE__ */ named('DatePicker', DatePickerRender);
